const repoInfo = $json;
const config = $('Config').first().json;
const count = repoInfo.stargazers_count || 0;
const perPage = 100;
const targetPage = Math.max(1, Math.ceil(count / perPage));

return [{
  json: {
    owner: config.owner,
    repo: config.repo,
    bootstrapBatchSize: config.bootstrapBatchSize || 5,
    maxHistory: config.maxHistory || 1000,
    stargazers_count: count,
    targetPage: targetPage,
    perPage: perPage
  }
}];

/**
 * Delta Detection & Persistent State Node
 * Reads persistent state via $getWorkflowStaticData('global')
 * Filters incoming stargazers to emit only genuinely new leads
 */
const staticData = $getWorkflowStaticData('global');
staticData.lastProcessedStarredAt = staticData.lastProcessedStarredAt || null;
staticData.processedUserIds = staticData.processedUserIds || [];

const rawItems = $input.all();
const config = $('Config').first().json;
const bootstrapLimit = config.bootstrapBatchSize || 5;
const maxHistory = config.maxHistory || 1000;

// Flatten stargazers list
let stargazers = [];
for (const item of rawItems) {
  if (Array.isArray(item.json)) {
    stargazers.push(...item.json);
  } else if (item.json && item.json.user && item.json.starred_at) {
    stargazers.push(item.json);
  }
}

// Sort chronologically ascending
stargazers.sort((a, b) => new Date(a.starred_at) - new Date(b.starred_at));

const processedSet = new Set(staticData.processedUserIds);
const newLeads = [];
let latestTimestamp = staticData.lastProcessedStarredAt;

if (!staticData.lastProcessedStarredAt) {
  // Initial Run: Bootstrap up to the latest batch
  const batch = stargazers.slice(-bootstrapLimit);
  for (const star of batch) {
    if (star.user && !processedSet.has(star.user.id)) {
      newLeads.push(star);
      processedSet.add(star.user.id);
      if (!latestTimestamp || new Date(star.starred_at) > new Date(latestTimestamp)) {
        latestTimestamp = star.starred_at;
      }
    }
  }
} else {
  // Subsequent Runs: Strictly new stars
  const lastCutoff = new Date(staticData.lastProcessedStarredAt);
  for (const star of stargazers) {
    if (!star.user) continue;
    const starTime = new Date(star.starred_at);
    const isNew = starTime > lastCutoff;
    const notSeen = !processedSet.has(star.user.id);

    if (isNew && notSeen) {
      newLeads.push(star);
      processedSet.add(star.user.id);
      if (!latestTimestamp || starTime > new Date(latestTimestamp)) {
        latestTimestamp = star.starred_at;
      }
    }
  }
}

// Cap history to maxHistory
let updatedIds = Array.from(processedSet);
if (updatedIds.length > maxHistory) {
  updatedIds = updatedIds.slice(-maxHistory);
}

// Commit persistent state
staticData.lastProcessedStarredAt = latestTimestamp;
staticData.processedUserIds = updatedIds;

// Return each new stargazer as a separate n8n item
return newLeads.map(lead => ({
  json: {
    starred_at: lead.starred_at,
    user: lead.user,
    login: lead.user.login,
    id: lead.user.id,
    avatar_url: lead.user.avatar_url,
    html_url: lead.user.html_url
  }
}));
